mapper.select:
SELECT favorite_folder_id AS folder_id, folder_nm AS folder_name, tenant_id, user_id
FROM public.tb_user_menu_favorite_folder
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
ORDER BY favorite_folder_id ASC

SELECT favorite_id, menu_id, favorite_folder_id AS folder_id, favorite_nm AS favorite_name
FROM public.tb_user_menu_favorite
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
ORDER BY COALESCE(favorite_folder_id, 0) ASC, favorite_id ASC

SELECT favorite_folder_id AS folder_id, folder_nm AS folder_name, tenant_id, user_id
FROM public.tb_user_menu_favorite_folder
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND favorite_folder_id = #{folderId}

SELECT COUNT(*)
FROM public.tb_user_menu_favorite
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND favorite_folder_id = #{folderId}

mapper.update:
UPDATE public.tb_user_menu_favorite_folder
SET folder_nm = #{folderName},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND favorite_folder_id = #{folderId}

mapper.delete:
DELETE FROM public.tb_user_menu_favorite_folder folder
WHERE folder.tenant_id = #{tenantId}
  AND folder.user_id = #{userId}
  AND folder.favorite_folder_id = #{folderId}
  AND NOT EXISTS (
      SELECT 1
      FROM public.tb_user_menu_favorite favorite
      WHERE favorite.tenant_id = folder.tenant_id
        AND favorite.user_id = folder.user_id
        AND favorite.favorite_folder_id = folder.favorite_folder_id
  )

mapper.insert:
INSERT INTO public.tb_user_menu_favorite (
    tenant_id, user_id, menu_id, favorite_folder_id, favorite_nm
)
VALUES (
