)

mapper.update:
UPDATE public.tb_user_menu_favorite
SET favorite_folder_id = #{folderId, jdbcType=BIGINT},
    favorite_nm = COALESCE(#{favoriteName, jdbcType=VARCHAR}, favorite_nm),
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND favorite_id = #{favoriteId}

mapper.delete:
DELETE FROM public.tb_user_menu_favorite
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND favorite_id = #{favoriteId}
